document.addEventListener('DOMContentLoaded', () => {
  initTheme();
  initHeader();
  initHeroSlider();
  initStatsCounter();
  initProductShowcase();
  initSearchModal();
  initMobileDrawer();
  initBackToTop();
});

/* ==========================================================================
   1. Theme Toggle (Dark / Light Mode)
   ========================================================================== */
function initTheme() {
  const themeToggleBtns = document.querySelectorAll('.theme-toggle-btn');
  const savedTheme = localStorage.getItem('scd-theme') || 'light';
  
  document.documentElement.setAttribute('data-theme', savedTheme);
  updateThemeIcons(savedTheme);

  themeToggleBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
      const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', newTheme);
      localStorage.setItem('scd-theme', newTheme);
      updateThemeIcons(newTheme);
    });
  });
}

function updateThemeIcons(theme) {
  const moonIcons = document.querySelectorAll('.icon-moon');
  const sunIcons = document.querySelectorAll('.icon-sun');
  
  if (theme === 'dark') {
    moonIcons.forEach(el => el.style.display = 'none');
    sunIcons.forEach(el => el.style.display = 'inline-block');
  } else {
    moonIcons.forEach(el => el.style.display = 'inline-block');
    sunIcons.forEach(el => el.style.display = 'none');
  }
}

/* ==========================================================================
   2. Sticky Header on Scroll
   ========================================================================== */
function initHeader() {
  const header = document.querySelector('.site-header');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 40) {
      header.classList.add('scrolled');
    } else {
      header.classList.remove('scrolled');
    }
  }, { passive: true });
}

/* ==========================================================================
   3. Hero Carousel / Slider
   ========================================================================== */
function initHeroSlider() {
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.hero-dot');
  const prevBtn = document.querySelector('.hero-arrow-btn.prev');
  const nextBtn = document.querySelector('.hero-arrow-btn.next');
  
  if (!slides.length) return;
  
  let currentSlide = 0;
  let slideInterval = null;

  function showSlide(index) {
    slides.forEach((s, i) => {
      s.classList.toggle('active', i === index);
    });
    dots.forEach((d, i) => {
      d.classList.toggle('active', i === index);
    });
    currentSlide = index;
  }

  function nextSlide() {
    let next = (currentSlide + 1) % slides.length;
    showSlide(next);
  }

  function prevSlide() {
    let prev = (currentSlide - 1 + slides.length) % slides.length;
    showSlide(prev);
  }

  function startAutoPlay() {
    stopAutoPlay();
    slideInterval = setInterval(nextSlide, 6000);
  }

  function stopAutoPlay() {
    if (slideInterval) clearInterval(slideInterval);
  }

  if (nextBtn) nextBtn.addEventListener('click', () => { nextSlide(); startAutoPlay(); });
  if (prevBtn) prevBtn.addEventListener('click', () => { prevSlide(); startAutoPlay(); });

  dots.forEach((dot, index) => {
    dot.addEventListener('click', () => {
      showSlide(index);
      startAutoPlay();
    });
  });

  const heroSection = document.querySelector('.hero-section');
  if (heroSection) {
    heroSection.addEventListener('mouseenter', stopAutoPlay);
    heroSection.addEventListener('mouseleave', startAutoPlay);
  }

  startAutoPlay();
}

/* ==========================================================================
   4. Stats Counter Animation
   ========================================================================== */
function initStatsCounter() {
  const statNumbers = document.querySelectorAll('.stat-number');
  if (!statNumbers.length) return;

  let hasAnimated = false;
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting && !hasAnimated) {
        hasAnimated = true;
        statNumbers.forEach(numEl => {
          const target = parseInt(numEl.getAttribute('data-target') || '0', 10);
          if (target > 0) animateCount(numEl, target, 1800);
        });
      }
    });
  }, { threshold: 0.2 });

  const statsBanner = document.querySelector('.stats-banner');
  if (statsBanner) observer.observe(statsBanner);
}

function animateCount(el, target, duration) {
  let start = 0;
  const stepTime = Math.abs(Math.floor(duration / 60));
  const increment = target / (duration / stepTime);
  
  const timer = setInterval(() => {
    start += increment;
    if (start >= target) {
      el.innerText = target;
      clearInterval(timer);
    } else {
      el.innerText = Math.floor(start);
    }
  }, stepTime);
}

/* ==========================================================================
   5. Product Showcase & Filter
   ========================================================================== */
function initProductShowcase() {
  const grid = document.getElementById('productGrid');
  const tabs = document.querySelectorAll('.tab-btn');
  const searchInput = document.getElementById('productSearchInput');
  
  if (!grid) return;

  let currentCategory = 'all';
  let searchQuery = '';

  function renderProducts() {
    const filtered = PRODUCTS_DATA.filter(p => {
      const matchCat = currentCategory === 'all' || 
        (currentCategory === 'eye' && (p.category.includes('안과') || p.name.includes('점안') || p.name.includes('주사') || p.name.includes('하메론') || p.name.includes('아이리스') || p.name.includes('비젠프리') || p.name.includes('바로낙') || p.name.includes('라타스트'))) ||
        (currentCategory === 'cardio' && (p.category.includes('순환기') || p.name.includes('자누') || p.name.includes('글리펜') || p.name.includes('다포가') || p.name.includes('로수틴') || p.name.includes('로스텐'))) ||
        (currentCategory === 'general' && (p.category.includes('일반') || p.category.includes('신제품') || p.name.includes('무코') || p.name.includes('벤라') || p.name.includes('미르텔')));
      
      const matchQuery = !searchQuery || 
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
        (p.ingredient && p.ingredient.toLowerCase().includes(searchQuery.toLowerCase()));

      return matchCat && matchQuery;
    });

    if (filtered.length === 0) {
      grid.innerHTML = `
        <div style="grid-column: 1 / -1; text-align: center; padding: 60px 20px; color: var(--text-muted);">
          <svg style="width: 48px; height: 48px; margin-bottom: 12px; stroke: currentColor;" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
            <path stroke-linecap="round" stroke-linejoin="round" d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z" />
          </svg>
          <p style="font-size: 1.1rem; font-weight: 600;">일치하는 제품이 없습니다.</p>
          <p style="font-size: 0.9rem; margin-top: 4px;">다른 검색어나 카테고리를 선택해 보세요.</p>
        </div>
      `;
      return;
    }

    grid.innerHTML = filtered.map(p => {
      const imgSrc = p.img ? `./images/${p.img}` : './images/v_free.jpg';
      const catBadge = p.category || '전문의약품';
      
      let summary = '무균 제조공정을 거친 삼천당제약의 대표 고품질 의약품입니다.';
      if (p.ingredient) {
        const lines = p.ingredient.split('\n').map(l => l.trim()).filter(l => l.length > 5);
        for (const l of lines) {
          if (l.includes('적응증') || l.includes('치료') || l.includes('개선') || l.includes('효능')) {
            summary = l.replace('적응증', '').replace(':', '').trim();
            break;
          }
        }
      }

      return `
        <div class="product-card" onclick="openProductModal('${p.id}')">
          <div class="product-img-wrapper">
            <span class="product-badge-cat">${catBadge}</span>
            <img src="${imgSrc}" alt="${p.name}" onerror="this.src='./images/mainImg02.jpg'" loading="lazy">
          </div>
          <div class="product-card-body">
            <h3 class="product-card-title">${p.name}</h3>
            <p class="product-card-sub">${summary}</p>
            <div class="product-card-footer">
              <span>상세 정보 보기</span>
              <svg width="16" height="16" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
                <path stroke-linecap="round" stroke-linejoin="round" d="M9 5l7 7-7 7" />
              </svg>
            </div>
          </div>
        </div>
      `;
    }).join('');
  }

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      tabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      currentCategory = tab.getAttribute('data-category') || 'all';
      renderProducts();
    });
  });

  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      searchQuery = e.target.value.trim();
      renderProducts();
    });
  }

  renderProducts();
}

/* ==========================================================================
   6. Product Detail Modal
   ========================================================================== */
window.openProductModal = function(productId) {
  const product = PRODUCTS_DATA.find(p => p.id === String(productId));
  if (!product) return;

  const modalBackdrop = document.getElementById('productModal');
  const modalContent = document.getElementById('productModalContent');
  if (!modalBackdrop || !modalContent) return;

  const imgSrc = product.img ? `./images/${product.img}` : './images/v_free.jpg';
  const detailsHtml = formatProductDetails(product.ingredient);

  modalContent.innerHTML = `
    <div class="modal-product-header">
      <div class="modal-product-img">
        <img src="${imgSrc}" alt="${product.name}" onerror="this.src='./images/mainImg02.jpg'">
      </div>
      <div class="modal-product-info">
        <span class="modal-badge">${product.category || '전문의약품'}</span>
        <h3>${product.name}</h3>
        <p style="font-size: 0.875rem; color: var(--text-secondary); margin-top: 4px;">
          삼천당제약(주) 제조 / KGMP & EU-GMP 기준 무균 생산
        </p>
      </div>
    </div>
    <div class="modal-product-details">
      ${detailsHtml}
    </div>
  `;

  modalBackdrop.classList.add('active');
  document.body.style.overflow = 'hidden';
};

window.closeProductModal = function() {
  const modalBackdrop = document.getElementById('productModal');
  if (modalBackdrop) {
    modalBackdrop.classList.remove('active');
    document.body.style.overflow = '';
  }
};

function formatProductDetails(rawText) {
  if (!rawText) {
    return '<p style="color: var(--text-muted);">상세 정보가 준비 중입니다. 고객지원센터로 문의해 주시기 바랍니다.</p>';
  }

  const sections = [
    { key: '성분·함량', title: '성분 및 함량' },
    { key: '적응증', title: '효능 및 효과' },
    { key: '용법·용량', title: '용법 및 용량' },
    { key: '포장단위', title: '포장 단위' },
    { key: '저장방법 및 사용기간', title: '저장방법 및 유효기간' }
  ];

  let rows = '';
  sections.forEach(sec => {
    const idx = rawText.indexOf(sec.key);
    if (idx !== -1) {
      let textChunk = rawText.substring(idx + sec.key.length);
      let nextMin = textChunk.length;
      sections.forEach(other => {
        if (other.key !== sec.key) {
          const oIdx = textChunk.indexOf(other.key);
          if (oIdx !== -1 && oIdx < nextMin) nextMin = oIdx;
        }
      });
      const val = textChunk.substring(0, nextMin).replace(/^[:\s\r\n]+/, '').trim();
      if (val) {
        rows += `
          <tr>
            <th>${sec.title}</th>
            <td>${val}</td>
          </tr>
        `;
      }
    }
  });

  if (!rows) {
    return `<div style="font-size: 0.88rem; line-height: 1.6; white-space: pre-line;">${rawText}</div>`;
  }

  return `<table class="modal-details-table"><tbody>${rows}</tbody></table>`;
}

/* ==========================================================================
   7. Quick Search Modal (Ctrl + K)
   ========================================================================== */
function initSearchModal() {
  const searchModal = document.getElementById('quickSearchModal');
  const searchTriggers = document.querySelectorAll('.search-trigger-btn');
  const searchInput = document.getElementById('quickSearchModalInput');
  const searchResults = document.getElementById('quickSearchResults');

  if (!searchModal) return;

  function openModal() {
    searchModal.classList.add('active');
    document.body.style.overflow = 'hidden';
    if (searchInput) {
      setTimeout(() => searchInput.focus(), 100);
      handleSearch(searchInput.value);
    }
  }

  function closeModal() {
    searchModal.classList.remove('active');
    document.body.style.overflow = '';
  }

  searchTriggers.forEach(btn => btn.addEventListener('click', openModal));

  window.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
      e.preventDefault();
      openModal();
    }
    if (e.key === 'Escape' && searchModal.classList.contains('active')) {
      closeModal();
    }
  });

  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      handleSearch(e.target.value);
    });
  }

  function handleSearch(q) {
    const query = q.trim().toLowerCase();
    if (!query) {
      const recs = PRODUCTS_DATA.slice(0, 6);
      renderSearchResults(recs, '추천 인기 제품');
      return;
    }

    const matches = PRODUCTS_DATA.filter(p => 
      p.name.toLowerCase().includes(query) || 
      (p.ingredient && p.ingredient.toLowerCase().includes(query))
    );

    renderSearchResults(matches, `검색 결과 (${matches.length}건)`);
  }

  function renderSearchResults(items, title) {
    if (!searchResults) return;
    if (items.length === 0) {
      searchResults.innerHTML = `
        <div style="text-align: center; padding: 40px 10px; color: var(--text-muted);">
          <p style="font-weight: 600;">검색 결과가 없습니다.</p>
        </div>
      `;
      return;
    }

    searchResults.innerHTML = `
      <div style="font-size: 0.8rem; font-weight: 700; color: var(--text-muted); margin-bottom: 12px; text-transform: uppercase;">
        ${title}
      </div>
      <div style="display: flex; flex-direction: column; gap: 8px;">
        ${items.map(p => `
          <div style="display: flex; align-items: center; justify-content: space-between; padding: 10px 14px; background: var(--bg-subtle); border-radius: var(--radius-sm); cursor: pointer; transition: background 0.2s;" 
               onmouseover="this.style.background='var(--primary-light)'" 
               onmouseout="this.style.background='var(--bg-subtle)'"
               onclick="closeSearchModal(); openProductModal('${p.id}')">
            <div style="display: flex; align-items: center; gap: 12px;">
              <span style="font-size: 0.725rem; font-weight: 700; background: var(--primary); color: white; padding: 2px 6px; border-radius: 4px;">
                ${p.category || '의약품'}
              </span>
              <span style="font-size: 0.92rem; font-weight: 600; color: var(--text-primary);">${p.name}</span>
            </div>
            <svg width="16" height="16" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" style="color: var(--text-muted);">
              <path stroke-linecap="round" stroke-linejoin="round" d="M9 5l7 7-7 7" />
            </svg>
          </div>
        `).join('')}
      </div>
    `;
  }
}

window.closeSearchModal = function() {
  const searchModal = document.getElementById('quickSearchModal');
  if (searchModal) {
    searchModal.classList.remove('active');
    document.body.style.overflow = '';
  }
};

/* ==========================================================================
   8. Mobile Drawer Navigation
   ========================================================================== */
function initMobileDrawer() {
  const mobileBtn = document.querySelector('.mobile-menu-btn');
  const drawer = document.querySelector('.mobile-drawer');
  const backdrop = document.getElementById('drawerBackdrop');
  const closeBtn = document.querySelector('.drawer-close-btn');

  function openDrawer() {
    if (drawer) drawer.classList.add('active');
    if (backdrop) backdrop.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  function closeDrawer() {
    if (drawer) drawer.classList.remove('active');
    if (backdrop) backdrop.classList.remove('active');
    document.body.style.overflow = '';
  }

  if (mobileBtn) mobileBtn.addEventListener('click', openDrawer);
  if (closeBtn) closeBtn.addEventListener('click', closeDrawer);
  if (backdrop) backdrop.addEventListener('click', closeDrawer);
}

/* ==========================================================================
   9. Floating Back-to-Top Button
   ========================================================================== */
function initBackToTop() {
  const fab = document.querySelector('.fab-top');
  if (!fab) return;

  window.addEventListener('scroll', () => {
    if (window.scrollY > 300) {
      fab.classList.add('visible');
    } else {
      fab.classList.remove('visible');
    }
  }, { passive: true });

  fab.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
}
